#include "process.h"
static void wipe(void *ptr,size_t n){volatile unsigned char *p=ptr;while(n--)*p++=0;}
void proc_clear(struct proc_group*g){wipe(g,sizeof *g);}
int proc_init(struct proc_group*g,unsigned n,uint64_t first){proc_clear(g);if(!n||n>PROC_MAX||!first||first>UINT64_MAX-(n-1))return 0;g->count=n;g->current=n-1;for(unsigned i=0;i<n;i++){g->slots[i].id=first+i;g->slots[i].state=PROC_READY;}return 1;}
int proc_next(struct proc_group*g){if(!g->count||g->current>=g->count)return -1;struct proc_slot *old=&g->slots[g->current];if(old->state==PROC_RUNNING)old->state=PROC_READY;for(unsigned i=1;i<=g->count;i++){unsigned k=(g->current+i)%g->count;if(g->slots[k].state==PROC_READY){g->current=k;g->slots[k].state=PROC_RUNNING;g->slots[k].slice=0;return (int)k;}}return -1;}
int proc_finish(struct proc_group*g,int result){if(!g->count||g->slots[g->current].state!=PROC_RUNNING)return -1;struct proc_slot*s=&g->slots[g->current];s->result=result;s->state=PROC_DONE;wipe(s->queue,sizeof s->queue);s->head=s->count=0;return proc_next(g);}
/* -1 no runnable processes; otherwise current slot. CPU ticks charged only to current slot. */
int proc_tick(struct proc_group*g){if(!g->count||g->slots[g->current].state!=PROC_RUNNING)return -1;struct proc_slot*s=&g->slots[g->current];if(++s->spent>=PROC_BUDGET)return proc_finish(g,PROC_TIMEOUT);if(++s->slice>=PROC_QUANTUM)return proc_next(g);return (int)g->current;}
long proc_send(struct proc_group*g,unsigned dest,const void*buf,size_t n){if(!g->count||g->slots[g->current].state!=PROC_RUNNING||dest>=g->count||dest==g->current||!buf||!n||n>PROC_MSG_MAX)return -22;struct proc_slot*s=&g->slots[dest];if(s->state==PROC_DONE)return -32;if(s->count==PROC_QUEUE)return -11;struct proc_message*m=&s->queue[(s->head+s->count)%PROC_QUEUE];m->sender=g->slots[g->current].id;m->len=n;const unsigned char*p=buf;for(size_t i=0;i<n;i++)m->data[i]=p[i];s->count++;return (long)n;}
long proc_receive(struct proc_group*g,void*buf,size_t n){if(!g->count||g->slots[g->current].state!=PROC_RUNNING||!buf||!n||n>PROC_MSG_MAX)return -22;struct proc_slot*s=&g->slots[g->current];if(!s->count)return -11;struct proc_message*m=&s->queue[s->head];if(n<m->len)return -90;unsigned char*p=buf;size_t len=m->len;for(size_t i=0;i<len;i++)p[i]=m->data[i];wipe(m,sizeof *m);s->head=(s->head+1)%PROC_QUEUE;s->count--;return (long)len;}
int proc_selftest(void){struct proc_group g;char b[4];int ok=proc_init(&g,2,1)&&proc_next(&g)==0&&proc_send(&g,1,"abc",3)==3&&proc_tick(&g)==0&&proc_tick(&g)==1&&proc_receive(&g,b,2)==-90&&proc_receive(&g,b,4)==3&&b[0]=='a'&&b[2]=='c'&&proc_receive(&g,b,4)==-11&&proc_finish(&g,0)==0&&proc_send(&g,1,"x",1)==-32&&proc_finish(&g,0)==-1;proc_clear(&g);return ok&&!g.count;}
